def verify():
    assert 10 * 9 // 2 == 45 and abs(12000 / 1e7 * 1e3 - 1.2) < 1e-9 and abs(2e5 / 2e8 * 1e3 - 1) < 1e-9
    assert 120 * 3 / 60 == 6
    b = lambda n, a: (a ** n / math.factorial(n)) / sum(a ** k / math.factorial(k) for k in range(n + 1))
    assert abs(b(2, 1) - 0.2) < 1e-12 and abs(b(1, 2) - 0.6667) < 1e-4
    assert abs(16 * 155.52 - 2488.32) < 1e-9 and abs(1 / (1 + 2 * 0.5) - 0.5) < 1e-12
    assert abs(999 / 1000 - 0.999) < 1e-12 and abs(525600 * 1e-4 - 52.56) < 1e-9 and abs(0.99 * 0.99 - 0.9801) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
